  String toString() {
    return (StringBuffer('ApprovalDecisionsCompanion(')
          ..write('id: $id, ')
          ..write('organizationId: $organizationId, ')
          ..write('branchId: $branchId, ')
          ..write('approvalRequestId: $approvalRequestId, ')
          ..write('decision: $decision, ')
